<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $mode === 'edit' ? 'Edit' : 'New' ?> account · Electric Demo</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f7fb}.card{border:0;border-radius:1rem;box-shadow:0 .4rem 1.5rem #12263a12}.navbar{background:#12263a}</style></head><body><nav class="navbar navbar-dark mb-4"><div class="container"><a class="navbar-brand" href="<?= base_url() ?>">⚡ Electric Demo</a><span class="text-white small"><?= esc($username) ?></span></div></nav><main class="container pb-5"><div class="card mx-auto" style="max-width:900px"><div class="card-body p-4 p-md-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="text-muted small text-uppercase mb-1">Customer account</p><h1 class="h3 mb-0"><?= $mode === 'edit' ? 'Edit account' : 'Create account' ?></h1></div><a class="btn btn-outline-secondary" href="<?= $account ? base_url('account/'.$account['id']) : base_url() ?>">Cancel</a></div><?php if ($message = session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc($message) ?></div><?php endif; ?><form method="post" action="<?= $account ? base_url('account/'.$account['id']) : base_url('account') ?>"><?= csrf_field() ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Account number</label><input class="form-control" name="account_number" value="<?= esc(old('account_number',$account['account_number']??'')) ?>" required></div><div class="col-md-6"><label class="form-label">Customer name</label><input class="form-control" name="customer_name" value="<?= esc(old('customer_name',$account['customer_name']??'')) ?>" required></div><div class="col-12"><label class="form-label">Address</label><textarea class="form-control" name="address" rows="3" required><?= esc(old('address',$account['address']??'')) ?></textarea></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?= esc(old('email',$account['email']??'')) ?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?= esc(old('phone',$account['phone']??'')) ?>"></div><div class="col-md-6"><label class="form-label">Meter number</label><input class="form-control" name="meter_number" value="<?= esc(old('meter_number',$account['meter_number']??'')) ?>"></div><div class="col-md-3"><label class="form-label">Connection type</label><select class="form-select" name="connection_type"><?php foreach(['residential','commercial','industrial'] as $option): ?><option value="<?= $option ?>" <?= old('connection_type',$account['connection_type']??'residential')===$option?'selected':'' ?>><?= ucfirst($option) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['active','inactive','suspended'] as $option): ?><option value="<?= $option ?>" <?= old('status',$account['status']??'active')===$option?'selected':'' ?>><?= ucfirst($option) ?></option><?php endforeach; ?></select></div></div><button class="btn btn-primary mt-4" type="submit"><?= $mode === 'edit' ? 'Save changes' : 'Create account' ?></button></form></div></div></main></body></html>
